# filename: Payment/services/notification_client.py

import logging
import os
import httpx

logger = logging.getLogger(__name__)

NOTIFICATION_SERVICE_URL = os.getenv(
    "NOTIFICATION_SERVICE_URL",
    "http://notification-service:8008"
).rstrip("/")


async def notify_event(
    event:          str,
    payment_id:     str,
    merchant_id:    str,
    amount:         float,
    currency:       str,
    customer_email: str | None = None,
    customer_name:  str | None = None,
    customer_phone: str | None = None,
    merchant_email: str | None = None,
    failure_reason: str | None = None,
    refund_amount:  float | None = None,
    metadata:       dict | None = None,
) -> bool:
    """
    Fire-and-forget — never raises.
    Payment flow must never fail because of a notification failure.
    """
    payload = {
        "event":          event,
        "payment_id":     payment_id,
        "merchant_id":    merchant_id,
        "amount":         amount,
        "currency":       currency,
        "customer_email": customer_email,
        "customer_name":  customer_name,
        "customer_phone": customer_phone,
        "merchant_email": merchant_email,
        "failure_reason": failure_reason,
        "refund_amount":  refund_amount,
        "metadata":       metadata,
    }
    try:
        async with httpx.AsyncClient(timeout=5.0) as client:
            resp = await client.post(
                f"{NOTIFICATION_SERVICE_URL}/notify",
                json=payload,
            )
            if resp.status_code == 200:
                logger.info("[NOTIFY] ✓ event=%s payment=%s", event, payment_id)
                return True
            logger.warning("[NOTIFY] ✗ HTTP %d event=%s", resp.status_code, event)
            return False
    except Exception as exc:
        logger.error("[NOTIFY] ✗ unreachable event=%s error=%s", event, exc)
        return False
